import{_ as n,C as r,c as d,o as a,a2 as t,b as l,w as s,a as o,G as u,a3 as p}from"./chunks/framework.DkPtUiZm.js";const f=JSON.parse(`{"title":"L'avatar","description":"","frontmatter":{},"headers":[],"relativePath":"guides/avatar.md","filePath":"guides/avatar.md","lastUpdated":1790233006000}`),c={name:"guides/avatar.md"};function h(m,e,k,g,v,E){const i=r("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="l-avatar" tabindex="-1">L&#39;avatar <a class="header-anchor" href="#l-avatar" aria-label="Permalink to &quot;L&#39;avatar&quot;">​</a></h1><h2 id="ce-qu-il-fallait-traiter" tabindex="-1">Ce qu&#39;il fallait traiter <a class="header-anchor" href="#ce-qu-il-fallait-traiter" aria-label="Permalink to &quot;Ce qu&#39;il fallait traiter&quot;">​</a></h2><p>L&#39;avatar affichait une image, trois tailles et des initiales. Trois manques sautaient aux yeux dès qu&#39;on l&#39;utilisait pour de vrai.</p><p><strong>Une image met du temps, échoue parfois, et manque souvent.</strong> Les trois cas doivent se ressembler à l&#39;écran, sinon une liste de participants se réorganise sous les yeux pendant qu&#39;elle charge.</p><p><strong>Six personnes, six pastilles identiques.</strong> Rien ne distinguait deux « AK » dans une même liste.</p><p><strong>Aucune pile.</strong> Chaque application réécrivait son empilement de participants.</p><h2 id="la-teinte-vient-du-nom" tabindex="-1">La teinte vient du nom <a class="header-anchor" href="#la-teinte-vient-du-nom" aria-label="Permalink to &quot;La teinte vient du nom&quot;">​</a></h2><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Avatar</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Aya Koffi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// toujours la même couleur, partout</span></span></code></pre></div><p>Un hachage minuscule sur le nom, modulo six teintes sémantiques. Déterministe : la même personne garde sa couleur d&#39;un écran à l&#39;autre et d&#39;une session à l&#39;autre, ce qui la rend reconnaissable avant même qu&#39;on lise son nom.</p><p>La fonction est volontairement triviale — <code>h * 31 + code</code> — parce qu&#39;elle tourne pour chaque avatar d&#39;une liste qui peut en compter des centaines. Un hachage cryptographique y coûterait mille fois plus pour un résultat visuellement identique. Le résultat est mémoïsé sur le nom.</p><p><code>tint</code> force la couleur quand l&#39;application en a une à elle.</p><h2 id="les-initiales" tabindex="-1">Les initiales <a class="header-anchor" href="#les-initiales" aria-label="Permalink to &quot;Les initiales&quot;">​</a></h2><p>Première et dernière partie du nom, pas les deux premières :</p><table tabindex="0"><thead><tr><th>Nom</th><th>Initiales</th><th>Pourquoi</th></tr></thead><tbody><tr><td><code>Jean-Baptiste Kouassi Mbella</code></td><td><code>JM</code></td><td>c&#39;est le nom de famille qui distingue</td></tr><tr><td><code>Marie de la Tour</code></td><td><code>MT</code></td><td>les particules sont écartées</td></tr><tr><td><code>Aya</code></td><td><code>AY</code></td><td>un seul mot se replie sur ses lettres</td></tr></tbody></table><h2 id="rien-ne-saute-pendant-le-chargement" tabindex="-1">Rien ne saute pendant le chargement <a class="header-anchor" href="#rien-ne-saute-pendant-le-chargement" aria-label="Permalink to &quot;Rien ne saute pendant le chargement&quot;">​</a></h2>',15)),(a(),l(p,null,{default:s(()=>[u(i,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20LR%0A%20%20R%5B%22repli%20peint%20d'embl%C3%A9e%3Cbr%2F%3Einitiales%2C%20teinte%22%5D%20--%3E%20A%7B%22image%20%3F%22%7D%0A%20%20A%20--%3E%7Caucune%7C%20R2%5B%22le%20repli%20reste%22%5D%0A%20%20A%20--%3E%7Cen%20attente%7C%20S%5B%22souffle%20l%C3%A9ger%20sur%20le%20repli%22%5D%0A%20%20A%20--%3E%7C%C3%A9chou%C3%A9e%7C%20R2%0A%20%20A%20--%3E%7Carriv%C3%A9e%7C%20F%5B%22fondu%20par-dessus%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<p>Le repli n&#39;est pas une alternative à l&#39;image : il est <strong>toujours</strong> peint, dessous. C&#39;est lui qui tient la place, et il reste si l&#39;image échoue. Aucune bascule, donc aucun saut de mise en page.</p><p>L&#39;image se fond par-dessus avec un très léger rapprochement d&#39;échelle. Pendant l&#39;attente, le repli respire — assez pour dire « ça arrive », pas assez pour attirer l&#39;œil dans une liste de cinquante.</p><p>Le nom n&#39;est jamais dans l&#39;<code>alt</code> : il est annoncé une seule fois par un texte masqué, statut compris. Un <code>alt</code> le répéterait aux lecteurs d&#39;écran.</p><h2 id="le-groupe" tabindex="-1">Le groupe <a class="header-anchor" href="#le-groupe" aria-label="Permalink to &quot;Le groupe&quot;">​</a></h2><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AvatarGroup</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> max</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spreadOnHover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {equipe.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">map</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Avatar</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{p.id} </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{p.nom} </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{p.photo} /&gt;)}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">AvatarGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Le groupe impose taille, forme et variante à ses enfants par contexte — sans quoi chaque avatar d&#39;une pile répéterait les mêmes props — et chaque enfant peut reprendre la main.</p><p>Au-delà de <code>max</code>, le reste est résumé par un compteur. Sans limite, une réunion de quarante personnes déborde de sa ligne et n&#39;apprend plus rien : au-delà de cinq visages, on ne lit plus des gens, on lit une foule.</p><h3 id="deux-details-qui-decident-du-resultat" tabindex="-1">Deux détails qui décident du résultat <a class="header-anchor" href="#deux-details-qui-decident-du-resultat" aria-label="Permalink to &quot;Deux détails qui décident du résultat&quot;">​</a></h3><p><strong>L&#39;ordre d&#39;empilement.</strong> Mettre le premier avatar devant semble logique, et c&#39;est un piège : chaque suivant est alors masqué <strong>à gauche</strong>, précisément là où commence la lecture. « AK » devenait « K ». Chaque avatar recouvre donc le précédent — l&#39;ordre de peinture naturel — et chacun garde au moins sa première initiale.</p><p><strong>Le liseré.</strong> Sans un contour de la couleur du fond, deux teintes voisines se fondent l&#39;une dans l&#39;autre et la pile devient une tache. Son épaisseur suit la taille : deux pixels fixes disparaissent sur un avatar de 4,5 rem.</p><p>Le chevauchement par défaut est d&#39;un quart. À un tiers, la seconde initiale était déjà rognée — mesuré à l&#39;écran, pas supposé.</p><h2 id="les-variantes" tabindex="-1">Les variantes <a class="header-anchor" href="#les-variantes" aria-label="Permalink to &quot;Les variantes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Valeurs</th></tr></thead><tbody><tr><td><code>variant</code></td><td><code>soft</code> (défaut), <code>solid</code>, <code>outline</code></td></tr><tr><td><code>shape</code></td><td><code>circle</code>, <code>rounded</code>, <code>square</code></td></tr><tr><td><code>size</code></td><td><code>xs</code>, <code>sm</code>, <code>md</code>, <code>lg</code>, <code>xl</code></td></tr><tr><td><code>status</code></td><td><code>online</code>, <code>busy</code>, <code>away</code>, <code>offline</code></td></tr><tr><td><code>tint</code></td><td>six teintes sémantiques, ou dérivée du nom</td></tr><tr><td><code>ring</code></td><td>un liseré qui détache du fond</td></tr><tr><td><code>onPress</code></td><td>rend l&#39;avatar actionnable — un menu de compte</td></tr></tbody></table><p>Tout repose sur une seule variable, <code>--sia-avatar-tint</code>, posée par une classe et consommée par les trois variantes. Changer de variante ne redéfinit donc jamais la couleur : c&#39;est ce qui permet à une teinte dérivée du nom de survivre à <code>soft</code>, <code>solid</code> et <code>outline</code> sans tripler les règles.</p><p>Les formes ont un rayon <strong>proportionnel</strong> à la taille : un carré arrondi de 2 rem et un de 5 rem n&#39;ont pas la même courbure apparente à rayon fixe.</p><blockquote><p>Un défaut trouvé en chemin : le repli n&#39;héritait pas de la courbure du parent. L&#39;ombre interne de la variante <code>outline</code> dessinait donc un cadre carré que le masque circulaire rognait — il n&#39;en restait que deux fragments verticaux. Visible seulement à fort grossissement.</p></blockquote><h2 id="prevu" tabindex="-1">Prévu <a class="header-anchor" href="#prevu" aria-label="Permalink to &quot;Prévu&quot;">​</a></h2><p><code>AppShell</code> posera cet avatar dans son en-tête de compte.</p>`,18))])}const b=n(c,[["render",h]]);export{f as __pageData,b as default};
